完全二叉树编号性质：节点i的左子=2i，右子=2i+1。从1走到n等价于将n的二进制表示去掉最高位后，0→L，1→R。

```cpp
#include <iostream>
using namespace std;

int main()
{
    long long n;
    cin >> n;
    char s[65];
    int len = 0;
    for (int i = 60; i >= 0; i--)
    {
        if (n >> i & 1)
        {
            for (int j = i - 1; j >= 0; j--)
                s[len++] = (n >> j & 1) ? 'R' : 'L';
            break;
        }
    }
    s[len] = '\0';
    cout << s << '\n';
    return 0;
}
```

完全二叉树的层序遍历性质：空节点之后不能出现非空节点。遍历序列，遇到第一个0后检查其后是否还有非0值。

```cpp
#include <iostream>
using namespace std;

int a[1005];

int main()
{
    int T;
    cin >> T;
    while (T--)
    {
        int n;
        cin >> n;
        for (int i = 0; i < n; i++) cin >> a[i];
        bool ok = true, seen_zero = false;
        for (int i = 0; i < n; i++)
        {
            if (a[i] == 0) seen_zero = true;
            else if (seen_zero) { ok = false; break; }
        }
        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```
